// Generator config for the zod schemas in src/gen/ (ADR-0027).
// Run scripts/gen-api-schema rather than invoking this directly: it refreshes
// openapi.json from the backend first.
import { defineConfig } from "@hey-api/openapi-ts";

export default defineConfig({
  input: "./openapi.json",
  output: {
    path: "./src/gen",
    header: [
      "// Generated by scripts/gen-api-schema from openapi.json. Do not edit.",
      "// Change the Pydantic model, then rerun scripts/gen-api-schema.",
    ],
  },
  plugins: [
    {
      name: "zod",
      // Component schemas only: services/api.ts in each app picks the schema
      // per endpoint, so per-operation aliases would only add noise.
      requests: false,
      responses: false,
      definitions: {
        // Keep the Pydantic class names (IOValue, not IoValue).
        case: "preserve",
        name: "{{name}}Schema",
        types: { infer: { case: "preserve", name: "{{name}}" } },
      },
      $resolvers: {
        // `additionalProperties: false` (Pydantic `extra="forbid"`, i.e. the
        // request models, ADR-0024) becomes z.strictObject. The built-in zod 4
        // resolver ignores it and would emit a stripping z.object.
        object(ctx) {
          if (ctx.schema.additionalProperties?.type !== "never") return undefined;
          return ctx
            .$(ctx.plugin.imports.z)
            .attr("strictObject")
            .call(ctx.nodes.shape(ctx));
        },
      },
    },
  ],
});
